for _ in range(int(input())):
	(r, c, x) = map(int, input().split())
	(a, b) = ([], [])
	for i in range(r):
		a.append(list(map(int, input().split())))
	for i in range(r):
		b.append(list(map(int, input().split())))
	for i in range(r):
		for j in range(c):
			a[i][j] -= b[i][j]
	for i in range(x - 1):
		k = i + x
		while k < r:
			for j in range(c):
				a[i][j] += a[k][j]
			k += x
	k = x - 1
	while k < r:
		for i in range(x - 1):
			for j in range(c):
				a[i][j] -= a[k][j]
		k += x
	for j in range(x - 1):
		k = j + x
		while k < c:
			for i in range(x - 1):
				a[i][j] += a[i][k]
			k += x
	k = x - 1
	while k < c:
		for j in range(x - 1):
			for i in range(x - 1):
				a[i][j] -= a[i][k]
		k += x
	ans = 'Yes'
	for i in range(x - 1):
		for j in range(x - 1):
			if a[i][j] != 0:
				ans = 'No'
				break
		if ans == 'No':
			break
	print(ans)
